49: function aggregate(config, sessionId) {
50:   let files = [];
51:   try {
52:     files = readdirSync(config.sessionsDir).filter((f) => f.endsWith(".costs.jsonl"));
53:   } catch (e) {
54:     return { ok: false, dir: config.sessionsDir, error: String(e?.message ?? e), models: [], sessions: [], total: emptyTotals() };
55:   }
56:   if (sessionId) {
57:     const want = sessionId.endsWith(".costs.jsonl") ? sessionId : `${sessionId}.costs.jsonl`;
58:     files = files.filter((f) => f === want || basename(f, ".costs.jsonl") === sessionId);
59:   }
60:   files = files.slice(0, config.maxFiles);
61: 
62:   const byModel = new Map();
63:   const sessions = new Set();
64:   for (const file of files) {
65:     let text;
66:     try {
67:       text = readFileSync(join(config.sessionsDir, file), "utf8");
68:     } catch {
69:       continue;
70:     }
71:     for (const raw of text.split(/\r?\n/)) {
72:       const line = raw.trim();
73:       if (line === "") continue;
74:       const rec = safeParse(line);
75:       if (!rec || typeof rec !== "object") continue;
76:       const model = typeof rec.model === "string" ? rec.model : "(unknown)";
77:       const u = rec.usage ?? {};
78:       const prompt = Number(u.prompt_tokens) || 0;
79:       const completion = Number(u.completion_tokens) || 0;
80:       const total = Number(u.total_tokens) || prompt + completion;
81:       let m = byModel.get(model);
82:       if (!m) {
83:         m = { model, prompt: 0, completion: 0, total: 0, calls: 0, roles: new Set() };
84:         byModel.set(model, m);
85:       }
86:       m.prompt += prompt;
87:       m.completion += completion;
88:       m.total += total;
89:       m.calls += 1;
90:       if (typeof rec.role === "string") m.roles.add(rec.role);
91:       if (typeof rec.session_id === "string") sessions.add(rec.session_id);
92:     }
93:   }
94: 
95:   const models = [...byModel.values()]
96:     .map((m) => ({ model: m.model, prompt: m.prompt, completion: m.completion, total: m.total, calls: m.calls, roles: [...m.roles].sort() }))
97:     .sort((a, b) => b.total - a.total);
98: 
99:   const total = models.reduce(
100:     (a, m) => {
101:       a.prompt += m.prompt;
102:       a.completion += m.completion;
103:       a.total += m.total;
104:       a.calls += m.calls;
105:       return a;
106:     },
107:     emptyTotals()
108:   );
109: 
110:   return { ok: true, dir: config.sessionsDir, sessions: [...sessions].sort(), models, total };
